$paths = @(
  "$env:USERPROFILE\.openviking\usage_audit.sqlite3",
  "$env:USERPROFILE\.openviking\data\usage_audit.sqlite3"
)
foreach($p in $paths){ if(Test-Path $p){ Get-Item $p | Select-Object FullName,Length,LastWriteTime } }
# also search openviking data dir
$ov = "$env:USERPROFILE\.openviking"
if(Test-Path $ov){ Get-ChildItem $ov -Recurse -Filter '*audit*' -File -ErrorAction SilentlyContinue | Select-Object FullName,Length,LastWriteTime | Format-Table -AutoSize }

$logs = Get-ChildItem "$env:USERPROFILE\.openviking" -Recurse -Filter '*recall*' -File -ErrorAction SilentlyContinue
if(-not $logs){ $logs = Get-ChildItem "$env:USERPROFILE\.dsh" -Recurse -Filter '*recall*' -File -ErrorAction SilentlyContinue }
$logs | Select-Object FullName,Length,LastWriteTime | Format-Table -AutoSize
# also check the plugin source for where recall is triggered
$plug = "$env:USERPROFILE\.dsh\profiles\web\node_modules\@openviking\dsh-memory-plugin"
if(Test-Path $plug){ Get-ChildItem $plug -Recurse -Include '*.js','*.mjs','*.cjs' -File -ErrorAction SilentlyContinue | Select-Object FullName,Length | Format-Table -AutoSize }

$plug = "$env:USERPROFILE\.dsh\profiles\web\node_modules\@openviking\dsh-memory-plugin"
if(Test-Path $plug){
  Get-ChildItem $plug -Recurse -Include '*.js','*.mjs','*.cjs' -File -ErrorAction SilentlyContinue |
    Where-Object { $_.FullName -notmatch 'node_modules\\@openviking\\dsh-memory-plugin\\node_modules' } |
    Select-Object @{n='Rel';e={$_.FullName.Replace($plug,'')}},Length | Format-Table -AutoSize
} else { "PLUGIN NOT AT $plug"; Get-ChildItem "$env:USERPROFILE\.dsh\profiles\web\node_modules\@openviking" -ErrorAction SilentlyContinue }

