// does not early-return null.
const fakeProfile = "# 当前用户\n- 身份：default (test) as of 2026-11-11";
async function fetchJSON(path, init, opts) {
  // resolveUserSpace -> likely GET something; lsDir -> fs/ls; readProfile -> content/read
  if (path.includes("/content/read") || path.includes("profile.md")) {
    return { ok: true, result: fakeProfile };
  }
  if (path.includes("/fs/ls")) {
    // return one entry so listings/prefs non-empty where needed
    return { ok: true, result: [{ name: "profile.md", type: "file" }] };
  }
  // user space resolution
  return { ok: true, result: "/user/default" , space: "default" };
}

const res = await buildProfileBlock(fetchJSON, 800, "");
console.log("returned null? ", res === null);
if (res) {
  const has = res.block.includes("openviking-hint") && res.block.includes("mcp_gateway(server=openviking");
  console.log("HINT_PRESENT=", has);
  console.log("--- block (first 600 chars) ---");
  console.log(res.block.slice(0, 600));
} else {
  console.log("HINT_PRESENT= false (block was null)");
}

